/**
 * pict-provider-graphlayout
 *
 * Pure, DOM-free node-placement algorithms and edge-routing themes for graph
 * canvases. These descriptors were extracted verbatim from pict-section-flow
 * (Phase 1b of the flow 2.0 plan); behavior is unchanged. pict-section-flow's
 * Layout service registers them, and Pict-Section-Flow.js re-exports the public
 * subset so the historical export surface is preserved.
 *
 * Layout algorithm descriptors are `{ Name, Label, Apply, DefaultParameters,
 * ParameterSchema }`. Edge-theme descriptors are `{ Name, GeneratePath,
 * AdjustLayout?, ResolveAttachment?, ... }`. Coerce / Rank / PerimeterMath are
 * internal helpers the descriptors depend on, exposed here so existing tests and
 * advanced consumers can reach them.
 *
 * The path-generation math (today pict-section-flow's PathGenerator service)
 * lands here in a follow-up step as a geometry-injected core.
 */

// Layout algorithm descriptors and their helpers
const libLayoutCoerce           = require('./layouts/Layout-Coerce.js');
const libLayoutRank             = require('./layouts/Layout-Rank.js');
const libLayoutCustom           = require('./layouts/Layout-Custom.js');
const libLayoutLayered          = require('./layouts/Layout-Layered.js');
const libLayoutStaggered        = require('./layouts/Layout-Staggered.js');
const libLayoutForcedFromCenter = require('./layouts/Layout-ForcedFromCenter.js');
const libLayoutGrid             = require('./layouts/Layout-Grid.js');
const libLayoutCircular         = require('./layouts/Layout-Circular.js');
const libLayoutTabular          = require('./layouts/Layout-Tabular.js');
const libLayoutColumnar         = require('./layouts/Layout-Columnar.js');

// Edge-routing theme descriptors and their helper
const libEdgePerimeterMath       = require('./edges/Edge-PerimeterMath.js');
const libEdgeBezier              = require('./edges/Edge-Bezier.js');
const libEdgeOrthogonal          = require('./edges/Edge-Orthogonal.js');
const libEdgeStraight            = require('./edges/Edge-Straight.js');
const libEdgeOrthogonalSnap      = require('./edges/Edge-OrthogonalSnap.js');
const libEdgePerimeter           = require('./edges/Edge-Perimeter.js');
const libEdgePerimeterLinear     = require('./edges/Edge-Perimeter-Linear.js');
const libEdgePerimeterOrthogonal = require('./edges/Edge-Perimeter-Orthogonal.js');

// Edge path-generation math (geometry-injected pure core)
const libPathGenerator = require('./PathGenerator-Core.js');

module.exports =
{
	// Edge path-generation math (bezier / orthogonal / multi-handle routing)
	PathGenerator: libPathGenerator,

	Layouts:
	{
		Coerce:           libLayoutCoerce,
		Rank:             libLayoutRank,
		Custom:           libLayoutCustom,
		Layered:          libLayoutLayered,
		Staggered:        libLayoutStaggered,
		ForcedFromCenter: libLayoutForcedFromCenter,
		Grid:             libLayoutGrid,
		Circular:         libLayoutCircular,
		Tabular:          libLayoutTabular,
		Columnar:         libLayoutColumnar
	},

	Edges:
	{
		PerimeterMath:       libEdgePerimeterMath,
		Bezier:              libEdgeBezier,
		Orthogonal:          libEdgeOrthogonal,
		Straight:            libEdgeStraight,
		OrthogonalSnap:      libEdgeOrthogonalSnap,
		Perimeter:           libEdgePerimeter,
		PerimeterLinear:     libEdgePerimeterLinear,
		PerimeterOrthogonal: libEdgePerimeterOrthogonal
	}
};
